import{_ as n,c as o,o as e,ae as a}from"./chunks/framework.Bi6zybwU.js";const h=JSON.parse('{"title":"Conditional Formatting","description":"Conditional Formatting","frontmatter":{"title":"Conditional Formatting","description":"Conditional Formatting"},"headers":[],"relativePath":"guide/column-settings/conditional-formatting.md","filePath":"guide/column-settings/conditional-formatting.md"}'),i={name:"guide/column-settings/conditional-formatting.md"};function l(s,t,r,c,g,d){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="conditional-formatting" tabindex="-1">Conditional Formatting <a class="header-anchor" href="#conditional-formatting" aria-label="Permalink to &quot;Conditional Formatting&quot;">​</a></h1><p>Conditions in table cells can change the column&#39;s data or highlight the specific cells you want your audience to focus on. Conditional formatting in Ninja Tables lets you add multiple conditions to table cells and the column/row the cell is in. Conditional Formatting is a Pro Feature! The cell value of the table changes in response to the conditions.</p><h2 id="applying-conditional-formatting-in-ninja-tables" tabindex="-1"><strong>Applying Conditional Formatting in Ninja Tables</strong> <a class="header-anchor" href="#applying-conditional-formatting-in-ninja-tables" aria-label="Permalink to &quot;**Applying Conditional Formatting in Ninja Tables**&quot;">​</a></h2><p>Read this simple guide to learn how to apply this feature.</p><ul><li>Firstly, you need to have a table designed beforehand.</li><li>There are two methods to configure <strong>Conditional Formatting</strong>.</li></ul><p>Go to the <strong>Table Configuration</strong> tab <strong>→</strong> Click on the <strong>Edit</strong> icon (Pencil Icon) on the right side of the tables columns and you will notice a drop-down. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-conditional-formatting-tab-1024x712.webp" alt="New Ui conditional formatting tab"></p><ul><li>Or you can do it by going over any column name and pressing the <strong>Edit</strong> icon from the <strong>Table</strong> <strong>Rows</strong> tab. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-All-tables-configuration-icon-1024x467.webp" alt="New Ui All tables configuration icon"></li><li>After that, a pop-up window will appear with various interactive options. Go to the top bar for <strong>Conditional Formatting</strong>.</li><li>Click on the <strong>Conditional Formatting</strong> tab. When you click the <strong>Add</strong> <strong>Condition</strong> button, multiple options to set conditions will appear with-</li></ul><p><strong>If Cell Value</strong> [Select] [Enter Value] <strong>Then</strong> [Select] [Enter Value]. <img src="https://ninjatables.com/wp-content/uploads/2023/03/Ninja-Tables-Add-Condition-1024x210.png" alt="Ninja Tables Add Condition"></p><ul><li><p>Let’s set the conditions differently as <strong>Equal, Not Equal, Contains, <strong>and</strong> Does not Contain</strong>. Then, you need to set some trigger values and then set options for which conditions will be applied. <img src="https://ninjatables.com/wp-content/uploads/2023/03/Ninja-Tables-Conditions-1024x240.png" alt="Ninja Tables Conditions"></p></li><li><p>From the 3rd box, you can set **Cell Options, Row Options, **and **Column Options **and apply the desired condition.</p></li><li><p>If you select Cell Options, the condition will only apply to cells</p></li><li><p>If you select Row Options, the condition will apply to the corresponding row</p></li><li><p>And if you select Column Options, the conditions will change the corresponding column</p></li></ul><p><img src="https://ninjatables.com/wp-content/uploads/2023/03/Set-cell-css-class.png" alt="Set-cell-css-class"></p><p><img src="https://ninjatables.com/wp-content/uploads/2023/03/Ninja-Tables-column-and-row-options-1024x333.png" alt="Ninja Tables column and row options"><img src="https://ninjatables.com/wp-content/uploads/2023/03/Conditional-formatting-column-options.png" alt="Conditional formatting column options"> Let&#39;s see how the conditions work.</p><ul><li>In this case, <strong>If Cell Value</strong> is Equal to <strong>Male,</strong> Then the <strong>Set cell color</strong> to red.</li><li>Also,** If Cell Value** is <strong>Equal</strong> to Female, Then the <strong>Set cell background</strong> <strong>color</strong> to brown.</li><li>Lastly, click on the <strong>Update</strong> button when the configuration is done. <img src="https://ninjatables.com/wp-content/uploads/2023/03/Ninja-Tables-added-Conditions-1024x262.png" alt="Ninja Tables added Conditions"></li><li>After applying Conditional Formatting, the table will look like the below screenshot – <img src="https://ninjatables.com/wp-content/uploads/2023/03/Table-Preview-conditional-formatting-added-1024x977.png" alt="Table Preview- conditional formatting added"></li></ul><h3 id="highlight-table-cells-with-conditions" tabindex="-1">Highlight Table Cells With Conditions <a class="header-anchor" href="#highlight-table-cells-with-conditions" aria-label="Permalink to &quot;Highlight Table Cells With Conditions&quot;">​</a></h3><p>Say you want your customers to pay attention to a specific product price. You can highlight the cell where the price is mentioned. <img src="https://ninjatables.com/wp-content/uploads/2023/09/highlighted-cell-1024x488.png" alt="highlighted cell"></p><h3 id="set-cell-css-class" tabindex="-1"><strong>Set Cell CSS class</strong> <a class="header-anchor" href="#set-cell-css-class" aria-label="Permalink to &quot;**Set Cell CSS class**&quot;">​</a></h3><p>Let’s discuss another cell option, the Set Cell CSS class.</p><ul><li>First, set the Cell option as <strong>Set cell CSS class</strong> and enter a value name as <strong>abc</strong> (it will be a CSS class name). <img src="https://ninjatables.com/wp-content/uploads/2023/03/Ninja-Tables-cell-CSS-class-1024x214.png" alt="Ninja Tables cell CSS class"></li><li>Then, navigate to the table’s** Custom CSS/JS** tab and write your CSS style. (It will apply to all of the Male values since it&#39;s the gender column)</li><li>Click on the** Save Custom CSS** button after you are done. <img src="https://ninjatables.com/wp-content/uploads/2023/03/Ninja-Tables-Custom-CSS-1024x347.png" alt="Ninja Tables Custom CSS"></li><li>See the preview of the table after adding the CSS. <img src="https://ninjatables.com/wp-content/uploads/2023/03/Preview-Table-1024x785.png" alt="Preview Table"></li></ul><h3 id="conditional-formatting-for-numeric-value-data" tabindex="-1"><strong>Conditional Formatting for Numeric Value</strong> Data <a class="header-anchor" href="#conditional-formatting-for-numeric-value-data" aria-label="Permalink to &quot;**Conditional Formatting for Numeric Value** Data&quot;">​</a></h3><p>When you select <strong>Numeric Value</strong> as a Data Type in column settings, there will be more options in <strong>Cell</strong> <strong>Value</strong>. <img src="https://ninjatables.com/wp-content/uploads/2023/03/Conditional-formatting-in-Numeric-value-1024x284.png" alt="COnditional formatting in data field"></p><ul><li>In the <strong>Age <strong>Column</strong>, if the Cell Value is Less Than <strong>Or</strong> Equal To <strong>25</strong>, Then <strong>the</strong> Set cell color</strong> (cell options) to maroon. <img src="https://ninjatables.com/wp-content/uploads/2023/03/Add-numeric-value-condition-1024x225.png" alt="Add numeric value condition"></li><li>See how the conditions work in a column with numeric data. All cell data with a value less than or equal to 25 are colored in maroon. <img src="https://ninjatables.com/wp-content/uploads/2023/03/Numeric-data-types-1024x704.png" alt="Numeric data types"></li></ul><h3 id="conditional-formatting-in-date-field" tabindex="-1"><strong>Conditional Formatting in Date Field</strong> <a class="header-anchor" href="#conditional-formatting-in-date-field" aria-label="Permalink to &quot;**Conditional Formatting in Date Field**&quot;">​</a></h3><p>When you select Date Field as a Data Type in column settings, there will be more options in <strong>Cell</strong> <strong>Value</strong>. Also, you need to take care of your <strong>Date</strong> <strong>Format</strong> in column settings because you will get the list of <strong>Example Usage</strong> in Conditional Formatting according to your chosen Date Format. <img src="https://ninjatables.com/wp-content/uploads/2023/03/COnditional-formatting-in-data-field-1024x519.png" alt="Conditional formatting in data field"></p><ul><li>Here is the list of Example Usage according to the chosen Date Format. <img src="https://ninjatables.com/wp-content/uploads/2023/03/Date-format-condition-add-1024x387.png" alt="Date format condition add"></li><li>Here, if the Cell Value is <strong>Less</strong> <strong>Than</strong> Today’s Date <strong>{date: MM/DD/YY}</strong> (this date format is taken from the below Example usage list), Then the <strong>Set</strong> <strong>cell</strong> <strong>color</strong> will be changed to Blue. <img src="https://ninjatables.com/wp-content/uploads/2023/03/Add-numeric-condition--1024x401.png" alt="Add numeric condition"></li><li>See the preview. The data with less than today&#39;s date are blue. <img src="https://ninjatables.com/wp-content/uploads/2023/03/Table-preview-numeric-formatting-1024x295.png" alt="Table preview numeric formatting"></li></ul><h3 id="set-row-css-class" tabindex="-1"><strong>Set Row CSS class</strong> <a class="header-anchor" href="#set-row-css-class" aria-label="Permalink to &quot;**Set Row CSS class**&quot;">​</a></h3><p>Let’s talk about another row option, the Set row CSS class, and how it works.</p><ul><li>First, set the Row option as <strong>Set row CSS class</strong> and enter a value name as <strong>hide</strong> (it will be a CSS class name). <img src="https://ninjatables.com/wp-content/uploads/2023/03/Ninja-Tables-row-css-class-1024x389.png" alt="Ninja Tables row css class"></li><li>Then, navigate to the table’s** Custom CSS/JS** tab and write your CSS style; it will apply to all of the dates which are less than Today’s Date values.</li><li>At last, click on the** Save Custom CSS** button after you are done. <img src="https://ninjatables.com/wp-content/uploads/2023/03/Add-Custom-CSS-for-tables-1024x351.png" alt="Add Custom CSS for tables"></li><li>Here in the preview, you can see the rest of the dates that are <strong>less</strong> <strong>than</strong> <strong>today’s</strong> <strong>date</strong> have been hidden here. <img src="https://ninjatables.com/wp-content/uploads/2023/03/Preview-Table-with-custom-css-1024x220.png" alt="Preview-Table-with custom css"> That’s how to set up <strong>Conditional</strong> <strong>Column</strong> <strong>Formatting</strong> in Tables!</li></ul>',26)])])}const u=n(i,[["render",l]]);export{h as __pageData,u as default};
